var BACK_IMG = ['/public/imazine/img/bk-cv-1.webp', '/public/imazine/img/bk-cv-2.webp', '/public/imazine/img/bk-cv-3.webp'];
var BACK_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
var backSeq = 0;
function backLine(d) { d = d instanceof Date && !isNaN(d) ? d : new Date(); return d.getFullYear() + ' in Frames · ' + BACK_MONTHS[d.getMonth()] + ' ' + d.getFullYear(); }
function backCover(d, no) {
  var el = document.createElement('div'); el.className = 'bk';
  el.setAttribute('role', 'img'); el.setAttribute('aria-label', 'Back cover');
  /* id di dalam SVG dibuat unik per salinan: halaman album admin memuat dua sampul belakang sekaligus */
  var p = 'bk' + (++backSeq) + '_';
  var esc = function (s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;'); };
  var dyn = '<text class="bk-tx" x="34.00" y="807.51">' + esc(backLine(d)) + '</text>';
  if (no && /^IMZ-[A-Z0-9]{6}$/.test(no)) dyn += '<text class="bk-tx" x="451.21" y="807.51">Kode booking</text><text class="bk-no" x="508.49" y="807.51">' + no + '</text>';
  el.innerHTML = BACK_SVG.replace(/id="/g, 'id="' + p).replace(/url\(#/g, 'url(#' + p).replace(/href="#/g, 'href="#' + p).replace('</svg>', dyn + '</svg>');
  BACK_IMG.forEach(function (src, i) {
    var im = document.createElement('img'); im.className = 'bk-cv bk-cv' + (i + 1); im.src = src; im.alt = ''; im.decoding = 'sync'; im.draggable = false;
    el.appendChild(im);
  });
  return el;
}
function spineEl() {
  var el = document.createElement('div'); el.className = 'spn'; el.setAttribute('aria-hidden', 'true');
  el.innerHTML = SPINE_SVG;
  var c = document.createElement('p'); c.className = 'spn-cr'; c.textContent = 'Designed by The Innovators Studio x Vier Moments ©';
  el.appendChild(c);
  return el;
}
